//! Headphone catalog: every headphone measurement of the
//! [AutoEq](https://github.com/jaakkopasanen/AutoEq) project (oratory1990,
//! Rtings, Innerfidelity, Headphone.com Legacy and community sources),
//! each paired with the target curve of its measurement rig.
//!
//! The data is one compact blob, `data/catalog.bin`, generated by
//! `scripts/build_catalog.py` and embedded with `include_bytes!`. It is parsed
//! once, on first use of [`Catalog::get`]. Curves are decoded on demand.
//! `data/catalog-sources.md` lists the sources, counts and targets.
//!
//! ## Targets and bass
//!
//! A measurement only makes sense against a target measured on the same kind
//! of rig, so every [`Entry`] carries the target AutoEq recommends for its
//! source, form and rig ([`Catalog::target`], always a "without bass"
//! version) and AutoEq's default bass shelf for that target
//! ([`Entry::default_bass_db`], a 105 Hz, Q 0.7 low shelf, the same shape as
//! [`DesignParams::bass_db`](crate::dsp::fit::DesignParams::bass_db)).
//!
//! ## Ranking
//!
//! When a headphone was measured by several sources, all of them are kept and
//! [`Entry::rank`] orders them with AutoEq's own source priority: oratory1990
//! first, then the GRAS / KEMAR-pinna rigs, then the rest.
//!
//! ```
//! use flatline::catalog::{Catalog, Form};
//! use flatline::dsp::fit;
//!
//! let cat = Catalog::get();
//! let hit = cat.search("dt 770", Some(Form::OverEar), 10)[0];
//! assert_eq!(hit.source, "oratory1990");
//! assert_eq!(cat.find(&hit.key()).map(|e| e.name), Some(hit.name));
//!
//! let params = fit::DesignParams { bass_db: hit.default_bass_db, ..Default::default() };
//! let d = fit::design(&cat.curve(hit), &cat.target(hit), &params, 48_000.0);
//! assert!(d.error_after_db < d.error_before_db);
//! ```

use crate::dsp::curve::Curve;
use std::sync::OnceLock;

static BLOB: &[u8] = include_bytes!("../data/catalog.bin");

const MAGIC: &[u8; 4] = b"FLC1";
const VERSION: u16 = 1;
const HEADER: usize = 40;
const ENTRY: usize = 32;
const TARGET: usize = 16;
const NONE: u32 = u32::MAX;
const FLAG_RIG_IN_KEY: u8 = 1;
const FLAG_GROUP_HAS_STOCK: u8 = 2;

/// Headphone form factor, as classified by AutoEq.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Form {
    /// Over-ear and on-ear headphones.
    OverEar,
    /// In-ear monitors (sealed, with eartips).
    InEar,
    /// Earbuds (unsealed, resting in the outer ear).
    Earbud,
}

impl Form {
    /// Every form, in filter order.
    pub const ALL: [Form; 3] = [Form::OverEar, Form::InEar, Form::Earbud];

    /// Short label for filters: "Over-ear", "In-ear", "Earbuds".
    pub fn label(self) -> &'static str {
        match self {
            Form::OverEar => "Over-ear",
            Form::InEar => "In-ear",
            Form::Earbud => "Earbuds",
        }
    }

    fn from_code(code: u8) -> Option<Form> {
        match code {
            0 => Some(Form::OverEar),
            1 => Some(Form::InEar),
            2 => Some(Form::Earbud),
            _ => None,
        }
    }
}

/// One measurement of one headphone by one source.
#[derive(Clone, Debug)]
pub struct Entry {
    /// Original AutoEq name, e.g. `Beyerdynamic DT 770 Pro (worn earpads)`.
    pub name: &'static str,
    /// Manufacturer, normalised with AutoEq's manufacturer index (aliases such
    /// as "Massdrop x Sennheiser" become "Sennheiser"), e.g. `Beyerdynamic`.
    pub brand: &'static str,
    /// Model without brand and variant, e.g. `DT 770 Pro`.
    pub model: &'static str,
    /// Variant tidied for display: the trailing parentheses of the name, with
    /// "earpads" / "eartips" shortened to "pads" / "tips" and a capital first
    /// letter, e.g. `Worn pads`, `ANC on`, `250 Ohm`. `None` for the stock
    /// headphone.
    pub variant: Option<&'static str>,
    /// Who measured it (AutoEq source folder), e.g. `oratory1990`, `Rtings`.
    pub source: &'static str,
    /// Measurement rig when known, e.g. `GRAS 45BC-10`, `HMS II.3`, `711`.
    pub rig: Option<&'static str>,
    /// Form factor.
    pub form: Form,
    /// AutoEq's default bass shelf for this entry's target, in dB (105 Hz,
    /// Q 0.7): 6 for the Harman over-ear 2018 targets, 8 for the AutoEq
    /// in-ear targets, 6 for LMG 5128, 6.5 for JM-1.
    pub default_bass_db: f64,
    /// AutoEq's priority of this source for this form: 0 is the most trusted
    /// (oratory1990), larger is less. Comparable within a form.
    pub rank: u8,
    target: u8,
    curve: u32,
    rig_in_key: bool,
    group_has_stock: bool,
}

impl Entry {
    /// Stable identifier for settings: `source/name`, or `source/rig/name`
    /// for sources that publish one folder per rig (Rtings, HypetheSonics
    /// in-ear), e.g. `oratory1990/Beyerdynamic DT 770 Pro`,
    /// `Rtings/HMS II.3/Sony WH-1000XM4`. See [`Catalog::find`].
    pub fn key(&self) -> String {
        match (self.rig_in_key, self.rig) {
            (true, Some(rig)) => format!("{}/{}/{}", self.source, rig, self.name),
            _ => format!("{}/{}", self.source, self.name),
        }
    }

    /// Brand, model and variant, e.g. `Beyerdynamic DT 770 Pro (Worn pads)`.
    pub fn display_name(&self) -> String {
        match self.variant {
            Some(v) => format!("{} {} ({})", self.brand, self.model, v),
            None => format!("{} {}", self.brand, self.model),
        }
    }

    fn matches_key(&self, key: &str) -> bool {
        let Some(rest) = key.strip_prefix(self.source).and_then(|r| r.strip_prefix('/')) else {
            return false;
        };
        let rest = match (self.rig_in_key, self.rig) {
            (true, Some(rig)) => match rest.strip_prefix(rig).and_then(|r| r.strip_prefix('/')) {
                Some(r) => r,
                None => return false,
            },
            _ => rest,
        };
        rest == self.name
    }
}

struct Target {
    label: &'static str,
    bass_db: f64,
    curve: u32,
}

/// The embedded headphone catalog. Get it with [`Catalog::get`].
pub struct Catalog {
    entries: Vec<Entry>,
    targets: Vec<Target>,
    grid: Vec<f64>,
    curves: &'static [u8],
    provenance: &'static str,
    index: SearchIndex,
}

impl Catalog {
    /// The catalog, parsed from the embedded blob on first call (a few ms),
    /// then shared.
    pub fn get() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| Catalog::parse(BLOB).expect("embedded data/catalog.bin is valid"))
    }

    /// Number of measurements.
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// `true` if the catalog holds no measurement (never for the embedded one).
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Every measurement, in the default order of [`Catalog::search`]
    /// (models measured by the most trusted source and by the most sources
    /// first; the measurements of one model together, best source first).
    pub fn entries(&self) -> &[Entry] {
        &self.entries
    }

    /// Where the data comes from, e.g. `AutoEq 7ae0f56d5307 (2025-07-20)`.
    pub fn provenance(&self) -> &'static str {
        self.provenance
    }

    /// Finds up to `limit` measurements matching `query`, best first,
    /// optionally restricted to one `form`.
    ///
    /// Matching ignores case, accents and punctuation: every word of the
    /// query must appear in the name (brand aliases and tidied variant
    /// included), or the query with spaces removed must appear in it, so
    /// "dt770", "DT 770" and "beyer 770" all find the DT 770 PRO.
    ///
    /// Ranking: an exact model match (the query is the model, or brand and
    /// model, and a stock measurement of it exists), then models starting
    /// with the query, then word-prefix matches, then other matches. Within
    /// each tier, models measured by the most trusted source and by the most
    /// sources come first, and the measurements of one model stay together,
    /// in source-rank order (oratory1990 first), stock before variants.
    ///
    /// An empty query lists every measurement in that order (popular, well
    /// measured models first). Runs in well under a millisecond.
    pub fn search(&self, query: &str, form: Option<Form>, limit: usize) -> Vec<&Entry> {
        if limit == 0 {
            return Vec::new();
        }
        let ix = &self.index;
        let mut spaced = String::new();
        fold_into(query, &mut spaced, true);
        let tokens: Vec<&str> = spaced.split_whitespace().collect();
        let compact: String = tokens.concat();
        let in_form_e = |e: &Entry| form.is_none_or(|f| e.form == f);

        if compact.is_empty() {
            return self.entries.iter().filter(|e| in_form_e(e)).take(limit).collect();
        }

        let word_starts: Vec<String> = tokens.iter().map(|t| format!(" {t}")).collect();
        let qmask = char_mask(&compact);
        let mut hits: Vec<u32> = Vec::new();
        for (i, (row, e)) in ix.rows.iter().zip(&self.entries).enumerate() {
            if qmask & !row.mask != 0 || !in_form_e(e) {
                continue;
            }
            let model = ix.s(row.model_c);
            let brand_model = ix.s(row.brand_model_c);
            let tier = if model == compact || brand_model == compact {
                if e.group_has_stock { 0 } else { 1 }
            } else if model.starts_with(&compact)
                || brand_model.starts_with(&compact)
                || ix.s(row.name_c).starts_with(&compact)
            {
                1
            } else {
                let hay = ix.s(row.hay);
                if word_starts.iter().all(|t| hay.contains(t.as_str())) {
                    2
                } else if tokens.iter().all(|t| hay.contains(t)) || compact_at_word_start(hay, &compact) {
                    3
                } else {
                    continue;
                }
            };
            hits.push((tier << 24) | i as u32);
        }
        if hits.len() > limit {
            hits.select_nth_unstable(limit - 1);
            hits.truncate(limit);
        }
        hits.sort_unstable();
        hits.into_iter().map(|k| &self.entries[(k & 0xFF_FFFF) as usize]).collect()
    }

    /// The measurement whose [`Entry::key`] is `key`.
    pub fn find(&self, key: &str) -> Option<&Entry> {
        self.entries.iter().find(|e| e.matches_key(key))
    }

    /// The measured frequency response of `e` (dB, 0 dB mean between 300 Hz
    /// and 3 kHz), on a 1/24-octave grid from 20 Hz to 20 kHz.
    pub fn curve(&self, e: &Entry) -> Curve {
        self.decode_curve(e.curve)
    }

    /// The target of `e`'s measurement rig, without bass shelf (add
    /// [`Entry::default_bass_db`] through
    /// [`DesignParams::bass_db`](crate::dsp::fit::DesignParams::bass_db)).
    pub fn target(&self, e: &Entry) -> Curve {
        self.decode_curve(self.targets[e.target as usize].curve)
    }

    /// Display name of `e`'s target, e.g. `Harman over-ear 2018`,
    /// `HMS II.3 Harman over-ear 2018`, `AutoEq in-ear`.
    pub fn target_name(&self, e: &Entry) -> &'static str {
        self.targets[e.target as usize].label
    }

    /// `points` levels (dB) spread evenly in log-frequency over 20 Hz–20 kHz,
    /// each the mean of its slice of the measurement: a cheap shape for list
    /// rows. Same 0 dB reference as [`Catalog::curve`].
    pub fn sparkline(&self, e: &Entry, points: usize) -> Vec<f32> {
        let mut cdb = vec![0i32; self.grid.len()];
        self.decode(e.curve, &mut cdb);
        let n = cdb.len();
        (0..points)
            .map(|k| {
                let lo = k * n / points;
                let hi = ((k + 1) * n / points).max(lo + 1).min(n);
                let sum: i32 = cdb[lo..hi].iter().sum();
                sum as f32 / (hi - lo) as f32 / 100.0
            })
            .collect()
    }

    fn decode_curve(&self, offset: u32) -> Curve {
        let mut cdb = vec![0i32; self.grid.len()];
        self.decode(offset, &mut cdb);
        Curve { freq: self.grid.clone(), db: cdb.into_iter().map(|v| v as f64 / 100.0).collect() }
    }

    /// Zigzag LEB128 deltas, centi-dB.
    fn decode(&self, offset: u32, out: &mut [i32]) {
        let mut p = offset as usize;
        let mut acc = 0i32;
        for v in out.iter_mut() {
            let (mut z, mut shift) = (0u32, 0u32);
            loop {
                let b = self.curves[p];
                p += 1;
                z |= u32::from(b & 0x7F) << shift;
                if b & 0x80 == 0 {
                    break;
                }
                shift += 7;
            }
            acc += (z >> 1) as i32 ^ -((z & 1) as i32);
            *v = acc;
        }
    }

    fn parse(blob: &'static [u8]) -> Result<Catalog, String> {
        let mut r = Reader { blob, pos: 0 };
        if r.bytes(4)? != MAGIC {
            return Err("bad magic".into());
        }
        if r.u16()? != VERSION {
            return Err("unsupported version".into());
        }
        let points = r.u16()? as usize;
        let f_min = r.f32()? as f64;
        let per_octave = r.f32()? as f64;
        let n_strings = r.u32()? as usize;
        let n_entries = r.u32()? as usize;
        let n_targets = r.u32()? as usize;
        let curve_len = r.u32()? as usize;
        let provenance_id = r.u32()?;
        r.u32()?;
        debug_assert_eq!(r.pos, HEADER);

        let offsets: Vec<usize> = (0..=n_strings).map(|_| r.u32().map(|v| v as usize)).collect::<Result<_, _>>()?;
        let text_len = *offsets.last().ok_or("no strings")?;
        let text = std::str::from_utf8(r.bytes(text_len)?).map_err(|e| e.to_string())?;
        let string = |id: u32| -> Result<&'static str, String> {
            let i = id as usize;
            if i >= n_strings {
                return Err(format!("bad string id {id}"));
            }
            text.get(offsets[i]..offsets[i + 1]).ok_or_else(|| format!("bad string {id}"))
        };
        let opt_string = |id: u32| if id == NONE { Ok(None) } else { string(id).map(Some) };

        let entry_bytes = r.bytes(n_entries * ENTRY)?;
        let target_bytes = r.bytes(n_targets * TARGET)?;
        let curves = r.bytes(curve_len)?;

        let mut targets = Vec::with_capacity(n_targets);
        for t in target_bytes.as_chunks::<TARGET>().0 {
            let mut r = Reader { blob: t, pos: 0 };
            let _file = string(r.u32()?)?;
            let label = string(r.u32()?)?;
            let bass_db = r.i16()? as f64 / 100.0;
            r.u16()?;
            let curve = r.u32()?;
            targets.push(Target { label, bass_db, curve });
        }

        let mut entries = Vec::with_capacity(n_entries);
        for e in entry_bytes.as_chunks::<ENTRY>().0 {
            let mut r = Reader { blob: e, pos: 0 };
            let name = string(r.u32()?)?;
            let brand = string(r.u32()?)?;
            let model = string(r.u32()?)?;
            let variant = opt_string(r.u32()?)?;
            let source = string(r.u32()?)?;
            let rig = opt_string(r.u32()?)?;
            let form = Form::from_code(r.u8()?).ok_or("bad form")?;
            let rank = r.u8()?;
            let flags = r.u8()?;
            let target = r.u8()?;
            let curve = r.u32()?;
            let t = targets.get(target as usize).ok_or("bad target index")?;
            entries.push(Entry {
                name,
                brand,
                model,
                variant,
                source,
                rig,
                form,
                default_bass_db: t.bass_db,
                rank,
                target,
                curve,
                rig_in_key: flags & FLAG_RIG_IN_KEY != 0,
                group_has_stock: flags & FLAG_GROUP_HAS_STOCK != 0,
            });
        }

        let grid = (0..points).map(|i| f_min * 2f64.powf(i as f64 / per_octave)).collect();
        let index = SearchIndex::build(&entries);
        Ok(Catalog { entries, targets, grid, curves, provenance: string(provenance_id)?, index })
    }
}

// ------------------------------------------------------------------ search --

/// Byte range in [`SearchIndex::text`].
#[derive(Clone, Copy)]
struct Span(u32, u32);

struct Row {
    /// Folded words of name, brand and variant, space separated, with a
    /// leading and trailing space (so " word" finds word starts).
    hay: Span,
    model_c: Span,
    brand_model_c: Span,
    name_c: Span,
    /// Characters present in `hay` (a–z, 0–9, other): rejects most rows
    /// before any string search.
    mask: u64,
}

/// Folded text of every entry, built once at load (about 1.5 ms). The
/// ranking order itself is precomputed by the generator: entries are stored
/// in the default order and carry a "model has a stock measurement" flag.
struct SearchIndex {
    text: String,
    rows: Vec<Row>,
}

impl SearchIndex {
    fn s(&self, span: Span) -> &str {
        &self.text[span.0 as usize..span.1 as usize]
    }

    fn build(entries: &[Entry]) -> SearchIndex {
        let span = |a: usize, b: usize| Span(a as u32, b as u32);
        let mut text = String::with_capacity(entries.len() * 100);
        let mut rows = Vec::with_capacity(entries.len());
        for e in entries {
            let a = text.len();
            text.push(' ');
            for w in [e.name, e.brand, e.variant.unwrap_or("")] {
                fold_into(w, &mut text, true);
                if !text.ends_with(' ') {
                    text.push(' ');
                }
            }
            let hay = span(a, text.len());
            let mask = char_mask(&text[a..]);
            let n = text.len();
            fold_into(e.name, &mut text, false);
            let name_c = span(n, text.len());
            let d = text.len();
            fold_into(e.brand, &mut text, false);
            let m = text.len();
            fold_into(e.model, &mut text, false);
            rows.push(Row { hay, model_c: span(m, text.len()), brand_model_c: span(d, text.len()), name_c, mask });
        }
        SearchIndex { text, rows }
    }
}

/// Appends `s` lower-cased with accents removed. With `spaced`, runs of
/// non-alphanumeric characters become one space; otherwise they are dropped.
fn fold_into(s: &str, out: &mut String, spaced: bool) {
    if s.is_ascii() {
        // Fast path (almost every name).
        let mut at_space = out.as_bytes().last().is_none_or(|&b| b == b' ');
        for &b in s.as_bytes() {
            if b.is_ascii_alphanumeric() {
                out.push(b.to_ascii_lowercase() as char);
                at_space = false;
            } else if spaced && !at_space {
                out.push(' ');
                at_space = true;
            }
        }
        return;
    }
    for c in s.chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
        } else if c.is_ascii() {
            separator(out, spaced);
        } else {
            for c in c.to_lowercase() {
                if let Some(f) = fold_latin(c) {
                    out.push_str(f);
                } else if c.is_alphanumeric() {
                    out.push(c);
                } else {
                    separator(out, spaced);
                }
            }
        }
    }
}

fn separator(out: &mut String, spaced: bool) {
    if spaced && !out.is_empty() && !out.ends_with(' ') {
        out.push(' ');
    }
}

fn fold_latin(c: char) -> Option<&'static str> {
    Some(match c {
        'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' | 'ā' | 'ă' | 'ą' => "a",
        'æ' => "ae",
        'ç' | 'ć' | 'č' => "c",
        'ď' | 'đ' | 'ð' => "d",
        'è' | 'é' | 'ê' | 'ë' | 'ē' | 'ė' | 'ę' | 'ě' => "e",
        'ì' | 'í' | 'î' | 'ï' | 'ī' | 'į' | 'ı' => "i",
        'ł' | 'ľ' => "l",
        'ñ' | 'ń' | 'ň' => "n",
        'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' | 'ō' | 'ő' => "o",
        'œ' => "oe",
        'ŕ' | 'ř' => "r",
        'ś' | 'š' | 'ş' => "s",
        'ß' => "ss",
        'ť' | 'ţ' => "t",
        'þ' => "th",
        'ù' | 'ú' | 'û' | 'ü' | 'ū' | 'ů' | 'ű' => "u",
        'ý' | 'ÿ' => "y",
        'ź' | 'ż' | 'ž' => "z",
        _ => return None,
    })
}

/// `true` if `compact` (no spaces) matches `hay` from the start of one of its
/// words, ignoring the spaces between words: "770pro" matches "dt 770 pro",
/// "rode" does not match "pro dekoni".
fn compact_at_word_start(hay: &str, compact: &str) -> bool {
    let (h, q) = (hay.as_bytes(), compact.as_bytes());
    (1..h.len()).filter(|&i| h[i - 1] == b' ' && h[i] != b' ').any(|start| {
        let mut chars = h[start..].iter().filter(|&&b| b != b' ');
        q.iter().all(|b| chars.next() == Some(b))
    })
}

fn char_mask(s: &str) -> u64 {
    s.bytes().fold(0u64, |m, b| {
        m | match b {
            b'a'..=b'z' => 1 << (b - b'a'),
            b'0'..=b'9' => 1 << (26 + b - b'0'),
            b' ' => 0,
            _ => 1 << 36,
        }
    })
}

// ------------------------------------------------------------------ reader --

struct Reader<'a> {
    blob: &'a [u8],
    pos: usize,
}

impl<'a> Reader<'a> {
    fn bytes(&mut self, n: usize) -> Result<&'a [u8], String> {
        let end = self.pos.checked_add(n).filter(|&e| e <= self.blob.len()).ok_or("truncated catalog")?;
        let b = &self.blob[self.pos..end];
        self.pos = end;
        Ok(b)
    }
    fn array<const N: usize>(&mut self) -> Result<[u8; N], String> {
        Ok(self.bytes(N)?.try_into().expect("length checked"))
    }
    fn u8(&mut self) -> Result<u8, String> {
        Ok(self.array::<1>()?[0])
    }
    fn u16(&mut self) -> Result<u16, String> {
        Ok(u16::from_le_bytes(self.array()?))
    }
    fn i16(&mut self) -> Result<i16, String> {
        Ok(i16::from_le_bytes(self.array()?))
    }
    fn u32(&mut self) -> Result<u32, String> {
        Ok(u32::from_le_bytes(self.array()?))
    }
    fn f32(&mut self) -> Result<f32, String> {
        Ok(f32::from_le_bytes(self.array()?))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::dsp::fit::{DesignParams, design};
    use crate::profiles;
    use std::collections::HashSet;
    use std::time::Instant;

    fn cat() -> &'static Catalog {
        Catalog::get()
    }

    fn dt770() -> &'static Entry {
        cat().find("oratory1990/Beyerdynamic DT 770 Pro").expect("DT 770 PRO in catalog")
    }

    #[test]
    fn blob_loads_and_every_curve_decodes() {
        let t0 = Instant::now();
        let c = Catalog::parse(BLOB).unwrap();
        eprintln!("parsed {} entries in {:.2} ms", c.len(), t0.elapsed().as_secs_f64() * 1e3);
        let t0 = Instant::now();
        let again = Catalog::parse(BLOB).unwrap();
        eprintln!("parsed again in {:.2} ms", t0.elapsed().as_secs_f64() * 1e3);
        assert_eq!(again.len(), c.len());
        assert!(c.len() > 5000, "{} entries", c.len());
        assert!(c.provenance().starts_with("AutoEq"));
        assert_eq!(c.grid.len(), 241);
        assert!((c.grid[0] - 20.0).abs() < 1e-9 && c.grid[240] >= 20_000.0);
        for e in c.entries() {
            for curve in [c.curve(e), c.target(e)] {
                assert_eq!(curve.db.len(), curve.freq.len());
                // Real data goes far down: oratory1990's EarFun Wave (Bluetooth
                // low-pass) reaches -182 dB at 20 kHz.
                assert!(curve.db.iter().all(|v| v.is_finite() && v.abs() < 250.0), "{} has a wild value", e.name);
            }
            assert!(!e.brand.is_empty() && !e.model.is_empty() && !e.source.is_empty());
            assert!(e.default_bass_db >= 0.0 && e.default_bass_db <= 10.0);
        }
    }

    #[test]
    fn counts_per_form_are_sane() {
        let count = |f: Form| cat().entries().iter().filter(|e| e.form == f).count();
        let (over, inear, bud) = (count(Form::OverEar), count(Form::InEar), count(Form::Earbud));
        eprintln!("over-ear {over}, in-ear {inear}, earbud {bud}");
        assert!(over > 2000 && inear > 3500 && bud > 50);
        assert_eq!(over + inear + bud, cat().len());
        let sources: HashSet<_> = cat().entries().iter().map(|e| e.source).collect();
        for s in ["oratory1990", "Rtings", "Innerfidelity", "Headphone.com Legacy", "Super Review"] {
            assert!(sources.contains(s), "missing source {s}");
        }
    }

    #[test]
    fn dt770_search_puts_oratory1990_first() {
        let hits = cat().search("dt 770", Some(Form::OverEar), 10);
        for h in &hits {
            eprintln!("{:<14} {:<40} {}", h.source, h.display_name(), cat().target_name(h));
        }
        assert_eq!(hits.len(), 10);
        assert!(hits.iter().all(|h| h.form == Form::OverEar));
        let top: Vec<_> = hits[..3].iter().map(|h| (h.source, h.model, h.variant)).collect();
        assert_eq!(
            top,
            [
                ("oratory1990", "DT 770 Pro", None),
                ("oratory1990", "DT 770 Pro", Some("Dekoni hybrid pads")),
                ("oratory1990", "DT 770 Pro", Some("Worn pads")),
            ]
        );
        assert!(hits[3..].iter().all(|h| h.source != "oratory1990" && h.model == "DT 770 Pro"));
        // Spelling and accents do not matter.
        for q in ["DT770", "beyer 770 pro", "beyerdynamic dt 770 pro"] {
            assert_eq!(cat().search(q, None, 1)[0].key(), dt770().key(), "query {q:?}");
        }
        assert!(cat().search("rode nth", None, 5).iter().any(|h| h.brand == "RØDE"));
        assert!(cat().search("ecoute", None, 5).iter().any(|h| h.name.starts_with("écoute")));
        assert!(cat().search("zzzz qqqq", None, 5).is_empty());
    }

    #[test]
    fn search_ranks_exact_model_before_prefix() {
        let hits = cat().search("hd 800", Some(Form::OverEar), 30);
        assert_eq!(hits[0].model, "HD 800");
        assert_eq!(hits[0].source, "oratory1990");
        let first_s = hits.iter().position(|h| h.model == "HD 800 S").expect("HD 800 S listed");
        assert!(hits[..first_s].iter().all(|h| h.model == "HD 800"));
    }

    #[test]
    fn search_filters_and_lists() {
        let all = cat().search("", None, usize::MAX);
        assert_eq!(all.len(), cat().len());
        let buds = cat().search("", Some(Form::Earbud), usize::MAX);
        assert!(buds.iter().all(|e| e.form == Form::Earbud) && !buds.is_empty());
        let pods = cat().search("airpods", Some(Form::Earbud), 50);
        assert!(!pods.is_empty() && pods.iter().all(|e| e.form == Form::Earbud && e.brand == "Apple"));
        assert!(cat().search("airpods", None, 0).is_empty());
    }

    #[test]
    fn search_is_fast() {
        let queries = ["d", "dt 770", "sennheiser hd", "airpods pro 2", "moondrop", "x", "7hz timeless", "zzz"];
        cat().search("warm up", None, 50);
        let n = 200;
        let t0 = Instant::now();
        for _ in 0..n {
            for q in queries {
                std::hint::black_box(cat().search(q, None, 50));
            }
        }
        let per = t0.elapsed().as_secs_f64() * 1e3 / (n * queries.len()) as f64;
        eprintln!("search: {per:.3} ms per query");
        if cfg!(not(debug_assertions)) {
            assert!(per < 1.0, "search takes {per:.3} ms");
        }
    }

    #[test]
    fn find_round_trips_every_key() {
        let mut seen = HashSet::new();
        for e in cat().entries() {
            let key = e.key();
            assert!(seen.insert(key.clone()), "duplicate key {key}");
            assert!(std::ptr::eq(cat().find(&key).unwrap(), e), "{key}");
        }
        assert!(cat().find("oratory1990/Nope 9000").is_none());
        assert!(cat().find("").is_none());
        let rtings = cat().entries().iter().find(|e| e.source == "Rtings").unwrap();
        assert!(rtings.key().starts_with("Rtings/HMS II.3/") || rtings.key().starts_with("Rtings/Bruel & Kjaer 5128/"));
    }

    #[test]
    fn names_are_split() {
        let e = cat().find("oratory1990/Beyerdynamic DT 770 Pro (worn earpads)").unwrap();
        assert_eq!((e.brand, e.model, e.variant), ("Beyerdynamic", "DT 770 Pro", Some("Worn pads")));
        assert_eq!(e.display_name(), "Beyerdynamic DT 770 Pro (Worn pads)");
        assert!(e.rig.is_some_and(|r| r.starts_with("GRAS")), "{:?}", e.rig);
        assert_eq!(dt770().variant, None);
        assert_eq!(cat().target_name(dt770()), "Harman over-ear 2018");
        assert_eq!(dt770().default_bass_db, 6.0);
        let iem = cat().entries().iter().find(|e| e.source == "oratory1990" && e.form == Form::InEar).unwrap();
        assert_eq!((cat().target_name(iem), iem.default_bass_db), ("AutoEq in-ear", 8.0));
    }

    #[test]
    fn sparkline_follows_curve() {
        let e = dt770();
        let s = cat().sparkline(e, 24);
        assert_eq!(s.len(), 24);
        let c = cat().curve(e);
        let first: f64 = c.db[..10].iter().sum::<f64>() / 10.0;
        assert!((s[0] as f64 - first).abs() < 0.01);
        assert!(cat().sparkline(e, 0).is_empty());
        assert_eq!(cat().sparkline(e, 500).len(), 500);
    }

    /// The catalog path must design as well as the hand-picked CSV path.
    #[test]
    fn design_matches_builtin_profile() {
        let p = DesignParams::default();
        let builtin = design(&profiles::HEADPHONES[0].curve(), &profiles::TARGETS[0].curve(), &p, 48_000.0);
        let e = dt770();
        let ours = design(&cat().curve(e), &cat().target(e), &p, 48_000.0);
        eprintln!(
            "built-in {:.3} -> {:.3} dB | catalog {:.3} -> {:.3} dB",
            builtin.error_before_db, builtin.error_after_db, ours.error_before_db, ours.error_after_db
        );
        // Same data as the built-in CSV, up to the 1/24-octave resampling and a level offset.
        let (csv, cat_curve) = (profiles::HEADPHONES[0].curve(), cat().curve(e));
        let diff: Vec<f64> = cat_curve.freq.iter().zip(&cat_curve.db).map(|(&f, &v)| v - csv.at(f)).collect();
        let mean = diff.iter().sum::<f64>() / diff.len() as f64;
        assert!(diff.iter().all(|d| (d - mean).abs() < 0.01), "catalog curve differs from the CSV");
        assert!((ours.error_before_db - builtin.error_before_db).abs() < 0.05);
        assert!((ours.error_after_db - builtin.error_after_db).abs() < 0.05);
        assert!(ours.error_after_db < 0.9);
    }
}
